(() => { const b64 = ""; const bin = atob(b64); const bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i); const file = new File([bytes], '1724773948895.jpg', { type: 'image/jpeg' }); const dt = new DataTransfer(); dt.items.add(file); const input = document.querySelector('input[type="file"]'); input.files = dt.files; input.dispatchEvent(new Event('change', { bubbles: true })); return 'img injected'; })()